fn test_conjugate() with IO {
    let o = oct(1.0, 0.5, 0.3, 0.2, 0.1, 0.15, 0.25, 0.05)
    let o_conj = oct_conj(o)

    // Conjugate should keep real part (a) and negate imaginary parts
    // Expected: 1 - 0.5i - 0.3j - 0.2k - 0.1l - 0.15il - 0.25jl - 0.05kl

    print("Test 4: Conjugate Operation")
    print("Conjugate negates all imaginary components")

    // Verify property: norm(o) = norm(conj(o))
