// ============================================================================
// HELPERS (must precede callers)
// ============================================================================

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 {
        return 0.0 - x
    }
    return x
}

fn sqrt_f64(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    var scaled = x
    var scale_back = 1.0
    while scaled < 1.0 {
        scaled = scaled * 4.0
        scale_back = scale_back * 2.0
    }
    while scaled > 4.0 {
        scaled = scaled * 0.25
        scale_back = scale_back * 0.5
    }
    var y = 1.5
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    y = 0.5 * (y + scaled / y)
    return y / scale_back
}

// ============================================================================
// DENSE VECTOR HELPERS
// ============================================================================

fn vec_dot(a: [f64; 128], b: [f64; 128], n: i32) -> f64 with Mut, Panic, Div {
    var sum = 0.0
    var i = 0
    while i < n {
        sum = sum + a[i] * b[i]
        i = i + 1
    }
    return sum
}

fn vec_copy(src: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var dst: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        dst[i] = src[i]
        i = i + 1
    }
    return dst
}

fn vec_sub(a: [f64; 128], b: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var result: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        result[i] = a[i] - b[i]
        i = i + 1
    }
    return result
}

fn vec_norm(x: [f64; 128], n: i32) -> f64 with Mut, Panic, Div {
    var sum = 0.0
    var i = 0
    while i < n {
        sum = sum + x[i] * x[i]
        i = i + 1
    }
    return sqrt_f64(sum)
}

// ============================================================================
// DATA STRUCTURES
// ============================================================================

struct SparseCSR {
    values: [f64; 1024],
    col_idx: [i32; 1024],
    row_ptr: [i32; 129],
    nrows: i32,
    ncols: i32,
    nnz: i32
}

struct CGMeta {
    iterations: i32,
    residual: f64,
    converged: bool
}

fn cg_solve_into(
    out_x: &![f64; 128],
    out_meta: &!CGMeta,
    a: SparseCSR,
    b: [f64; 128],
    x0: [f64; 128],
    n: i32,
    tol: f64,
    max_iter: i32
) with Mut, Panic, Div {
    var x: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        x[i] = x0[i]
        i = i + 1
    }

    let ax = sparse_matvec(a, x, n)
    var r = vec_sub(b, ax, n)
    var p = vec_copy(r, n)
    var rsold = vec_dot(r, r, n)

    if sqrt_f64(rsold) < tol {
        i = 0
        while i < n {
            out_x[i] = x[i]
            i = i + 1
        }
        out_meta.iterations = 0
        out_meta.residual = sqrt_f64(rsold)
        out_meta.converged = true
        return
    }

    var iter = 0
    var converged = false
    var done = false
    while iter < max_iter && !done {
        let ap = sparse_matvec(a, p, n)
        let pap = vec_dot(p, ap, n)
        if abs_f64(pap) < 1e-30 {
            done = true
        } else {
            let alpha = rsold / pap

            i = 0
            while i < n {
                x[i] = x[i] + alpha * p[i]
                i = i + 1
            }

            i = 0
            while i < n {
                r[i] = r[i] - alpha * ap[i]
                i = i + 1
            }

            let rsnew = vec_dot(r, r, n)

            if sqrt_f64(rsnew) < tol {
                converged = true
                done = true
            } else {
                let beta = rsnew / rsold
                i = 0
                while i < n {
                    p[i] = r[i] + beta * p[i]
                    i = i + 1
                }

                rsold = rsnew
            }
        }
        iter = iter + 1
    }

    let final_res = sqrt_f64(vec_dot(r, r, n))

    i = 0
    while i < n {
        out_x[i] = x[i]
        i = i + 1
    }

    out_meta.iterations = iter
    out_meta.residual = final_res
    out_meta.converged = converged
}

// ============================================================================
// CONSTRUCTION
// ============================================================================

fn sparse_new(nrows: i32, ncols: i32) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: nrows,
        ncols: ncols,
        nnz: 0
    }
    var i = 0
    while i <= nrows {
        result.row_ptr[i] = 0
        i = i + 1
    }
    return result
}

fn sparse_from_triplets(
    rows: [i32; 1024],
    cols: [i32; 1024],
    vals: [f64; 1024],
    count: i32,
    nrows: i32,
    ncols: i32
