    rows[4] = 2; cols[4] = 0; vals[4] = 5.0
    rows[5] = 2; cols[5] = 2; vals[5] = 6.0

    let a = sparse_from_triplets(rows, cols, vals, 6, 3, 3)

    let at = sparse_transpose(a)
    let att = sparse_transpose(at)

    // Check (A^T)^T == A
    var err = 0.0
    var i = 0
    while i < 3 {
        var j = 0
        while j < 3 {
            let diff = abs_f64(sparse_get(att, i, j) - sparse_get(a, i, j))
            if diff > err {
                err = diff
            }
            j = j + 1
        }
        i = i + 1
    }

    // Also check A^T values directly
    let at_10 = sparse_get(at, 1, 0)  // should be A[0,1] = 2
    let at_01 = sparse_get(at, 0, 1)  // should be A[1,0] = 3

    print("  max_err=")
